function getExInfo(name){
  const key=name.toLowerCase().replace(/[^a-z\s]/g,'').trim();
  for(const k of Object.keys(EX_INFO)){
    if(key.includes(k)||k.includes(key.split(' ').slice(0,2).join(' '))){return EX_INFO[k];}
  }
  return null;
}

// ── FIREBASE EXERCISE LOADER ──────────────────────────────────────────────────
// Loads admin-added exercise info from Firebase and merges with built-in EX_INFO
let _fbExLoaded = false;
async function loadAdminExercises(token) {
  if (_fbExLoaded) return;
  try {
    const r = await fetch('https://gym-tracker-4d57d-default-rtdb.firebaseio.com/adminExercises.json?auth=' + token);
    const data = await r.json();
    if (data) {
      Object.values(data).forEach(ex => {
        if (!ex?.name) return;
        const key = ex.name.toLowerCase().replace(/[^a-z\s]/g, '').trim();
        EX_INFO[key] = {
          gif: ex.gif || '',
          muscles: (ex.muscles || '').split(',').map(s => s.trim()).filter(Boolean),
          why: ex.why || '',
          how: ex.how || [],
          mistakes: ex.mistakes || []
        };
      });
    }
    _fbExLoaded = true;
  } catch (_) {}
}
